 updateSupplies(){if(!this.player||!this.save.survival?.provisions)return;const changed=!this.restoring&&supplies.observeSources(this.save,this.player.model.position);for(const i of this.world.interactions||[]){if(i.kind==='apple-tree'){i.usedUntil=this.save.survival.provisions.trees[i.treeId]?.readyAt||0;const ready=i.usedUntil<=this.save.playTime;for(const m of i.fruits||[])m.visible=ready;for(const m of i.signs||[])m.material.color.setHex(ready?0xef997b:0x788880);}if(i.kind==='rations'){const ready=!supplies.rationReason(this.save);for(const m of i.signs||[])m.material.color.setHex(ready?0xe5cc88:0x788880);}if(i.kind==='drink'){const source=supplies.WATER_SOURCES.find(s=>s.id===i.sourceId),ready=supplies.sourceReady(this.save,source);for(const m of i.signs||[])m.material.color.setHex(ready?0x91eafb:0xbfa277);}}if(changed&&!this.restoring){this.persist();this.emit('refreshPanel');}}
 spawnFoodDrop(position,existing=null){if(!this.world?.interactions)return null;const nearby=[[0,0],[1,0],[-1,0],[0,1],[0,-1],[2,0],[-2,0],[0,2],[0,-2]];const spot=existing?{x:existing.x,z:existing.z}:nearby.map(([dx,dz])=>({x:position.x+dx,z:position.z+dz})).find(({x,z})=>this.canStandAt(x,z));if(!spot||!this.canStandAt(spot.x,spot.z))return null;const needs=this.save.survival;if(!existing&&needs.drops.length>=24)this.removeFoodDrop(needs.drops[0].id);const drop=existing||{id:uid(),region:this.save.region,x:spot.x,z:spot.z,createdAt:this.save.playTime};if(!existing)needs.drops.push(drop);const x=spot.x,z=spot.z,y=this.world.height(x,z),meshes=[];if(this.world.owned){const fruit=this.world.owned(new THREE.Mesh(new THREE.DodecahedronGeometry(.32,1),new THREE.MeshStandardMaterial({color:0xe86768,emissive:0x6c2222,emissiveIntensity:.32})));fruit.position.set(x,y+.5,z);meshes.push(fruit);const leaf=this.world.owned(new THREE.Mesh(new THREE.ConeGeometry(.13,.28,5),new THREE.MeshStandardMaterial({color:0x8ddc78})));leaf.position.set(x,y+.85,z);leaf.rotation.z=.45;meshes.push(leaf);}this.world.interactions.push({kind:'food',dropId:drop.id,x,z,meshes,get name(){return t('survival.eatDrop');}});return drop;}
