 if(i.kind==='fishing'){if(!this.save.inventory['fishing-rod']){this.notify(t('field.rodNeeded'),t('field.rodShop'));return;}const entries=this.biomeById.get(this.save.region).spawnTable.filter(x=>x.method==='fishing'&&this.eligible(x));if(!entries.length){this.notify(t('field.quietWater'),t('field.tryWeather'));return;}const entry=entries[this.spawnIndex++%entries.length];i.usedUntil=this.save.playTime+5;this.notify(t('field.bite'));this.world.beam(this.player.model.position.clone().add(new THREE.Vector3(0,1,0)),new THREE.Vector3(i.x-4,.5,i.z),0xe3e7d8,.015,1);this.schedule(1.2,()=>this.spawn(entry.speciesId,{entry,x:i.x+2,z:i.z+3}));return;}
