 async specialEncounter(a,x=6,z=1){if(!requirementsMet(a.requirements,this.save)){this.notify(t('research.moreDiscovery'),this.requirementText(a.requirements));return;}if(a.speciesId===151&&!this.save.flags['mew-puzzle']){this.notify(t('field.memoryMissing'),t('field.memoryOrderLong'));return;}if(this.wild.some(w=>w.id===a.speciesId&&w.hp>0)){this.notify(t('research.waiting'));return;}if(a.method==='fossil'){const item=a.requirements.item;if(!this.save.inventory[item])return;this.save.inventory[item]--;}this.closePanel();this.notify(niceLocal(a.questId),a.kind==='boss'?t('research.sanctuaryResponding'):t('research.appeared'));const spawnSave=this.save,spawnEpoch=this.regionEpoch;let spawned;try{spawned=await this.spawn(a.speciesId,{x,z,boss:a.kind==='boss',quest:a,level:a.method==='fossil'?20:a.method==='dojo'?35:null});}catch(error){if(a.method==='fossil'&&this.save===spawnSave&&this.regionEpoch===spawnEpoch&&!this.restoring&&!this.survivalDying){this.save.inventory[a.requirements.item]++;this.persist();}throw error;}if(this.save!==spawnSave||this.regionEpoch!==spawnEpoch||this.restoring)return;if(!spawned&&a.method==='fossil')this.save.inventory[a.requirements.item]++;this.persist();}
 requirementText(req={}){const parts=[];if(req.caughtCount)parts.push(t('research.registeredRequirement',{required:req.caughtCount,current:caughtCount(this.save)}));if(req.item)parts.push(niceLocal(req.item));if(req.bosses)parts.push(t('research.bossRequirement',{pokemon:req.bosses.map(id=>this.byId.get(id).name).join(', ')}));if(req.time)parts.push(niceLocal(req.time));if(req.weather)parts.push(niceLocal(req.weather));return parts.join(' · ')||t('research.defaultHint');}
